create table public.data_intake_actions (
"id" uuid default gen_random_uuid() not null,
"session_id" uuid not null,
"candidate_id" uuid,
"actor_user_id" uuid,
"action" text not null,
"before_data" jsonb,
"after_data" jsonb,
"reason" text,
"created_at" timestamp with time zone default now() not null,
CHECK ((action = ANY (ARRAY['create'::text, 'classify'::text, 'extract'::text, 'validate'::text, 'reconcile'::text, 'edit'::text, 'confirm'::text, 'reject'::text, 'cancel'::text, 'retry'::text, 'commit'::text, 'fail'::text]))),
PRIMARY KEY (id)
);
create table public.data_intake_sessions (
"id" uuid default gen_random_uuid() not null,
"submitted_by" uuid,
"person_id" uuid,
"family_id" uuid,
"family_person_id" uuid,
"channel" text default 'line'::text not null,
"status" text default 'collecting'::text not null,
"input_count" integer default 0 not null,
"context_snapshot" jsonb default '{}'::jsonb not null,
"created_at" timestamp with time zone default now() not null,
"updated_at" timestamp with time zone default now() not null,
"expires_at" timestamp with time zone,
CHECK ((input_count >= 0)),
PRIMARY KEY (id),
CHECK ((status = ANY (ARRAY['collecting'::text, 'classified'::text, 'review'::text, 'confirmed'::text, 'rejected'::text, 'cancelled'::text, 'expired'::text, 'committed'::text, 'failed'::text])))
);
create table public.data_intake_sources (
"id" uuid default gen_random_uuid() not null,
"session_id" uuid not null,
"submitted_by" uuid,
"source_kind" text not null,
"document_type" text default 'unknown'::text not null,
"raw_text" text,
"source_url" text,
"source_document_id" uuid,
"source_metadata" jsonb default '{}'::jsonb not null,
"classification_confidence" numeric,
"created_at" timestamp with time zone default now() not null,
"storage_asset_id" uuid,
"line_message_id" text,
CHECK (((classification_confidence >= (0)::numeric) AND (classification_confidence <= (1)::numeric))),
CHECK ((document_type = ANY (ARRAY['medication_label'::text, 'medication_list'::text, 'prescription'::text, 'dispense_summary'::text, 'receipt'::text, 'appointment'::text, 'medical_document'::text, 'free_text'::text, 'unknown'::text, 'other'::text]))),
PRIMARY KEY (id),
CHECK ((source_kind = ANY (ARRAY['text'::text, 'image'::text, 'document'::text, 'line_message'::text, 'other'::text])))
);
create table public.health_measurements (
"id" uuid default gen_random_uuid() not null,
"person_id" uuid not null,
"measurement_type" text not null,
"measured_at" timestamp with time zone default now() not null,
"value_numeric" numeric,
"value_text" text,
"unit" text,
"systolic" numeric,
"diastolic" numeric,
"context" text,
"notes" text,
"source_type" text,
"created_by" uuid,
"created_at" timestamp with time zone default now() not null,
"deleted_at" timestamp with time zone,
CHECK (((value_numeric IS NOT NULL) OR (value_text IS NOT NULL) OR (systolic IS NOT NULL) OR (diastolic IS NOT NULL))),
PRIMARY KEY (id)
);
create table public.medical_documents (
"id" uuid default gen_random_uuid() not null,
"person_id" uuid not null,
"encounter_id" uuid,
"organization_id" uuid,
"document_type" text not null,
"document_date" date,
"title" text,
"storage_bucket" text,
"storage_path" text,
"source_channel" text,
"original_filename" text,
"mime_type" text,
"checksum_sha256" text,
"extraction_status" text default 'not_started'::text not null,
"uploaded_by" uuid,
"metadata" jsonb default '{}'::jsonb not null,
"created_at" timestamp with time zone default now() not null,
"updated_at" timestamp with time zone default now() not null,
"deleted_at" timestamp with time zone,
"storage_asset_id" uuid,
"treatment_episode_id" uuid,
"medical_record_request_id" uuid,
"service_period_start" date,
"service_period_end" date,
"received_at" timestamp with time zone,
PRIMARY KEY (id)
);
create table public.phms_storage_assets (
"id" uuid default gen_random_uuid() not null,
"bucket_id" text not null,
"object_name" text not null,
"asset_kind" text not null,
"lifecycle_state" text default 'temporary'::text not null,
"person_id" uuid,
"permission_resource" text default 'health'::text not null,
"original_filename" text,
"mime_type" text,
"byte_size" bigint,
"checksum_sha256" text,
"created_by" uuid,
"captured_at" timestamp with time zone,
"confirmed_by" uuid,
"confirmed_at" timestamp with time zone,
"metadata" jsonb default '{}'::jsonb not null,
"created_at" timestamp with time zone default now() not null,
"updated_at" timestamp with time zone default now() not null,
"deleted_at" timestamp with time zone,
CHECK ((bucket_id = ANY (ARRAY['phms-intake-temp'::text, 'phms-medical-sources'::text, 'phms-medication-media'::text, 'phms-exports'::text]))),
CHECK ((((bucket_id = 'phms-intake-temp'::text) AND (asset_kind = 'intake_source'::text) AND (lifecycle_state = ANY (ARRAY['temporary'::text, 'deleted'::text]))) OR ((bucket_id = 'phms-medical-sources'::text) AND (asset_kind = 'medical_document'::text) AND (lifecycle_state = ANY (ARRAY['confirmed'::text, 'deleted'::text])) AND (person_id IS NOT NULL)) OR ((bucket_id = 'phms-medication-media'::text) AND (asset_kind = 'medication_media'::text) AND (lifecycle_state = ANY (ARRAY['confirmed'::text, 'deleted'::text])) AND (person_id IS NOT NULL)) OR ((bucket_id = 'phms-exports'::text) AND (asset_kind = 'export'::text) AND (lifecycle_state = ANY (ARRAY['generated'::text, 'deleted'::text]))))),
CHECK (((byte_size IS NULL) OR (byte_size > 0))),
CHECK ((asset_kind = ANY (ARRAY['intake_source'::text, 'medical_document'::text, 'medication_media'::text, 'export'::text]))),
UNIQUE (bucket_id, object_name),
CHECK ((((bucket_id = 'phms-intake-temp'::text) AND (object_name ~* '^intake/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(jpg|jpeg|png|webp|pdf)$'::text)) OR ((bucket_id = 'phms-medical-sources'::text) AND (object_name ~* '^persons/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/documents/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(jpg|jpeg|png|webp|pdf)$'::text)) OR ((bucket_id = 'phms-medication-media'::text) AND (object_name ~* '^persons/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/medications/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(jpg|jpeg|png|webp)$'::text)) OR ((bucket_id = 'phms-exports'::text) AND (object_name ~* '^users/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/exports/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(pdf|csv|json)$'::text)))),
CHECK ((permission_resource = ANY (ARRAY['health'::text, 'medications'::text, 'appointments'::text]))),
PRIMARY KEY (id),
CHECK (((checksum_sha256 IS NULL) OR (checksum_sha256 ~ '^[0-9a-fA-F]{64}$'::text))),
CHECK ((lifecycle_state = ANY (ARRAY['temporary'::text, 'confirmed'::text, 'generated'::text, 'deleted'::text])))
);
